def bind_controller(controller):
    """Use the running controller explicitly for shared reporting helpers."""
    global _controller
    _controller = controller


from types import ModuleType as _NDO_ModuleType

class _NDO_ModuleView(_NDO_ModuleType):
    """A live view of prefixed globals, including mutable test injection points.

    No source loading, generated modules, or external dependencies are involved.
    """
    def __init__(self, name, prefix):
        super().__init__(name)
        self.__dict__['_prefix'] = prefix

    def __getattr__(self, name):
        child = self.__name__ + '.' + name
        if child in _NDO_MODULES:
            return _NDO_MODULES[child]
        try:
            return globals()[self._prefix + name]
        except KeyError:
            raise AttributeError(name)

    def __setattr__(self, name, value):
        if name.startswith('__') or name == '_prefix':
            super().__setattr__(name, value)
        else:
            globals()[self._prefix + name] = value

    def __delattr__(self, name):
        try:
            del globals()[self._prefix + name]
        except KeyError:
            raise AttributeError(name)

