    if len(bases) != 1 or not isinstance(bases[0], dict):
        return None
    polobject = bases[0].get('polobject')
    if not isinstance(polobject, dict):
        return None
    tag = polobject.get('msoTag')
    if not isinstance(tag, dict):
        return None
    is_shadow = tag.get('isShadow', False)
    if not isinstance(is_shadow, bool):
        return None
    if not is_shadow:
        return False
    preferred = epg.get('preferredGroup', False)
    if not isinstance(preferred, bool):
        return None
    if not preferred:
        return False
    shadow_info = epg.get('shadowInfo', bases[0].get('shadowInfo'))
    if not isinstance(shadow_info, dict):
        return None
    reasons = []
    for entry in shadow_info.values():
        if not isinstance(entry, dict) or not isinstance(entry.get('shadowReason'), dict):
            return None
        reason = entry['shadowReason'].get('shadowReasonPG')
        if not isinstance(reason, str) or not reason.strip():
            return None
        reasons.append(reason.strip().casefold())
    return 'created' in reasons

