def _ndo_ndo_checks_ndo_defect_validation___authoritative_site_ids(collections):
    """Return the active site inventory and whether dual evidence conflicts.

    A populated ``site2`` collection supersedes the legacy ``site`` collection.
    A present-but-empty ``site2`` collection falls back to a populated legacy
    collection.  The shadowed inventory does not add IDs, but an overlapping ID
    with a different customer name is conflicting evidence and fails closed.
    """
    if collections.get('site2'):
        authoritative_name = 'site2'
        shadow_name = 'site'
    elif collections.get('site'):
        authoritative_name = 'site'
        shadow_name = 'site2'
    elif 'site2' in collections:
        authoritative_name = 'site2'
        shadow_name = 'site'
    elif 'site' in collections:
        authoritative_name = 'site'
        shadow_name = 'site2'
    else:
        return (set(), True)
    identity_fields = ('_id', 'id', 'siteId', 'siteID')
    authoritative = {}
    for site in collections.get(authoritative_name, ()):
        if not isinstance(site, dict):
            return (set(), True)
        site_id = _ndo_ndo_checks_ndo_defect_validation___unambiguous_identifier(site, identity_fields)
        if not site_id or site_id in authoritative:
            return (set(), True)
        authoritative[site_id] = _ndo_ndo_checks_ndo_defect_validation___object_name(site, ('displayName', 'name'))
    shadow = {}
    for site in collections.get(shadow_name, ()):
        if not isinstance(site, dict):
            continue
        identifiers = _ndo_ndo_checks_ndo_defect_validation___identifier_values(site, identity_fields)
        if len(identifiers) != 1:
            if identifiers.intersection(authoritative):
                return (set(), True)
            continue
        site_id = next(iter(identifiers))
        site_name = _ndo_ndo_checks_ndo_defect_validation___object_name(site, ('displayName', 'name'))
        if site_id in shadow:
            prior_name = shadow[site_id]
            if prior_name and site_name and (prior_name != site_name):
                return (set(), True)
            continue
        shadow[site_id] = site_name
    for site_id in set(authoritative).intersection(shadow):
        authoritative_name_value = authoritative[site_id]
        shadow_name_value = shadow[site_id]
        if authoritative_name_value and shadow_name_value and (authoritative_name_value != shadow_name_value):
            return (set(), True)
    return (set(authoritative), False)

