def _ndo_ndo_checks_ndo_defect_validation___customer_compact_lines(validation, width, color=False, include_header=True, include_clear_result=True, include_next_steps=True, include_references=True, reference_plan=None):
    if not isinstance(reference_plan, _ndo_ndo_checks_ndo_defect_validation__ReferencePlan):
        reference_plan = _ndo_ndo_checks_ndo_defect_validation___reference_plan_for_defect_validation(validation)
    lines = []
    if include_header:
        path_label = 'Configuration-check scope: ' if validation.path.classification == _ndo_ndo_checks_ndo_defect_validation__ALL_REVIEWED else 'Upgrade path:  '
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('', _ndo_ndo_checks_ndo_defect_validation__CUSTOMER_SECTION_TITLE, width))
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('Source release: ', validation.path.source_release or 'Not specified', width))
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap(path_label, validation.path.customer_description, width))
    visible = [check for check in validation.checks if check.state != _ndo_ndo_checks_ndo_defect_validation__SKIPPED]
    findings = [check for check in visible if check.state == _ndo_ndo_checks_ndo_defect_validation__MATCHED and check.finding_class == _ndo_ndo_checks_ndo_defect_validation__ACTION_REQUIRED]
    advisories = [check for check in visible if check.state == _ndo_ndo_checks_ndo_defect_validation__MATCHED and check.finding_class == _ndo_ndo_checks_ndo_defect_validation__ADVISORY]
    coverage_limitations = validation.customer_coverage_limitations()
    if visible and lines:
        lines.append('')
    if findings:
        if validation.incomplete:
            warning = '! INCOMPLETE COVERAGE - REVIEW REQUIRED'
            warning_detail = '{0} configuration {1} were detected, but not all applicable checks could be fully evaluated.'.format(len(findings), 'issue' if len(findings) == 1 else 'issues')
        else:
            warning = '! WARNING - ATTENTION REQUIRED'
            warning_detail = '{0} configuration {1} must be corrected before the upgrade.'.format(len(findings), 'issue' if len(findings) == 1 else 'issues')
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', warning, width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_YELLOW, color=color))
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('  ', warning_detail, width))
        lines.append('')
        for issue_index, check in enumerate(findings, 1):
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', 'ISSUE {0} OF {1}'.format(issue_index, len(findings)), width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_YELLOW, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', check.customer_name, width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_CYAN, color=color))
            object_label = 'object' if check.affected_object_count == 1 else 'objects'
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', '! ATTENTION REQUIRED · {0} affected {1}'.format(check.affected_object_count, object_label), width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_YELLOW, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', 'DETECTED', width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_CYAN, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('', _ndo_ndo_checks_ndo_defect_validation___customer_issue_message(check), width))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', 'AFFECTED CONFIGURATION', width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_CYAN, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___customer_locator_compact_lines(check, width, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', 'RECOMMENDED ACTION', width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_CYAN, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('', _ndo_ndo_checks_ndo_defect_validation___action_with_citation(check.remediation, reference_plan.citation_for_rule(check.rule_id)), width))
            lines.append('')
    if advisories:
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_colored_wrap('', 'DATA HEALTH ADVISORY', width, ansi_color=_ndo_ndo_checks_ndo_defect_validation__ANSI_CYAN, color=color))
        lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('', 'The reviewed destination tolerates the following persisted residue; it does not by itself prevent the upgrade.', width))
        for check in advisories:
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('', check.customer_name, width))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___customer_locator_compact_lines(check, width, color=color))
            lines.extend(_ndo_ndo_checks_ndo_defect_validation___console_wrap('Optional action: ', check.remediation, width, '                 '))
