# Former module: ndo_offline
"""Offline adapter: privately prepare an export and run the shared NDO suite."""
from contextlib import contextmanager as _ndo_ndo_offline__contextmanager
from datetime import datetime as _ndo_ndo_offline__datetime, timezone as _ndo_ndo_offline__timezone
import hashlib as _ndo_ndo_offline__hashlib
import filecmp as _ndo_ndo_offline__filecmp
import json as _ndo_ndo_offline__json
import logging as _ndo_ndo_offline__logging
import os as _ndo_ndo_offline__os
from pathlib import Path as _ndo_ndo_offline__Path
import re as _ndo_ndo_offline__re
import shutil as _ndo_ndo_offline__shutil
import sys as _ndo_ndo_offline__sys
import tarfile as _ndo_ndo_offline__tarfile
import tempfile as _ndo_ndo_offline__tempfile

def _ndo_ndo_offline___snapshot(artifact, started, metadata=None):
    """Use export member paths, never the customer's filename or file mtime."""
    timestamps = set()
    if metadata and metadata.get('timestamp'):
        timestamps.add(metadata['timestamp'])
    with _ndo_ndo_offline__tarfile.open(str(artifact), 'r:*') as archive:
        for member in archive:
            for match in _ndo_ndo_offline__re.finditer('(?:mso_db_json_|msc-db-json-|^|/)(\\d{14})(?!\\d)', member.name):
                timestamps.add(match.group(1))
    match = _ndo_ndo_offline__re.search('(?:mso_db_json_|ndo_db_json_|ndo[-_]dump[-_].*?|ndo[-_]backup[-_].*?)(\\d{14})(?!\\d)', artifact.name)
    if match:
        timestamps.add(match.group(1))
    if len(timestamps) == 1:
        timestamp = timestamps.pop()
        try:
            when = _ndo_ndo_offline__datetime.strptime(timestamp, '%Y%m%d%H%M%S').replace(tzinfo=_ndo_ndo_offline__timezone.utc)
            age = max(0, int((started - when).total_seconds()))
            return {'timestamp': timestamp, 'age_seconds': age, 'stale': age > 86400}
        except ValueError:
            pass
    return {'timestamp': None, 'age_seconds': None, 'stale': False}

def _ndo_ndo_offline___bundle(root, destination, artifact, limit):
    files = [root / name for name in ('validation_summary.txt', 'validation_details.json', 'ndo-findings.txt', 'nd_validation_debug.log')]
    files += [root / 'ndo-evidence' / 'configuration-checks.log']
    if artifact is not None and artifact.stat().st_size <= limit:
        files.append(artifact)
    with _ndo_ndo_offline__tarfile.open(str(destination), 'w:gz') as bundle:
        for path in files:
            if path.is_file() and (not path.is_symlink()):
                bundle.add(str(path), arcname=str(_ndo_ndo_offline__Path('final-results') / path.relative_to(root)), recursive=False)

def _ndo_ndo_offline__run_offline(args, working_dir=None):
    materialize_techsupport_dump = _NDO_MODULES['techsupport_to_ndo_backup'].materialize_techsupport_dump
    validate_ndo_suite = _NDO_MODULES['ndo_checks.ndo_validation_suite'].validate_ndo_suite
    _configuration_coverage_is_incomplete = _NDO_MODULES['ndo_checks.ndo_validation_suite']._configuration_coverage_is_incomplete
    started = _ndo_ndo_offline__datetime.now(_ndo_ndo_offline__timezone.utc)
    working = (_ndo_ndo_offline__Path.cwd() if working_dir is None else _ndo_ndo_offline__Path(working_dir)).resolve()
    root = working / 'final-results'
    source = _ndo_ndo_offline__Path(args.tech_support).absolute()
    stage = None
    artifact = None
    handler = None
    config_log = root / 'ndo-evidence' / 'configuration-checks.log'
    log = _ndo_ndo_offline__logging.getLogger('ndo_offline')
    try:
        for directory in (root, root / 'ndo-evidence'):
            if directory.is_symlink():
                raise ValueError('offline output directory is a symlink: {}'.format(directory))
            directory.mkdir(mode=448, exist_ok=True)
        for name in ('validation_summary.txt', 'validation_details.json', 'ndo-findings.txt', 'nd_validation_debug.log'):
            output = root / name
            if output.is_symlink() or (output.exists() and source.exists() and _ndo_ndo_offline__os.path.samefile(output, source)):
                raise ValueError('unsafe offline output destination: {}'.format(output))
        if config_log.is_symlink() or (config_log.exists() and source.exists() and _ndo_ndo_offline__os.path.samefile(config_log, source)):
            raise ValueError('unsafe offline diagnostic destination: {}'.format(config_log))
        debug = root / 'nd_validation_debug.log'
        handler = _ndo_ndo_offline__logging.FileHandler(str(debug), mode='w')
        handler.setFormatter(_ndo_ndo_offline__logging.Formatter('%(asctime)s %(levelname)s %(message)s'))
        log.addHandler(handler)
        log.setLevel(_ndo_ndo_offline__logging.DEBUG)
        stage = _ndo_ndo_offline__Path(_ndo_ndo_offline__tempfile.mkdtemp(prefix='offline-', dir=str(working)))
        _ndo_ndo_offline__os.chmod(str(stage), 448)
        log.info('Preparing offline NDO input %s', source.name)
        metadata = {}
        prepared, release = materialize_techsupport_dump(source, stage, source_release=args.source_release, max_bytes=args.ndo_max_backup_bytes, metadata=metadata)
        if prepared.stat().st_size > args.ndo_max_backup_bytes:
            raise ValueError('NDO backup exceeds --ndo-max-backup-bytes')
        snapshot = _ndo_ndo_offline___snapshot(prepared, started, metadata)
        if snapshot['timestamp'] is None and _ndo_ndo_offline__tarfile.is_tarfile(str(source)):
            snapshot = _ndo_ndo_offline___snapshot(source, started)
        diagnostics = _ndo_ndo_offline__Path(_ndo_ndo_offline__tempfile.mkdtemp(prefix='offline-', dir=str(root / 'ndo-evidence')))
        artifact = diagnostics / 'mongo-json-backup.tar'
        _ndo_ndo_offline__shutil.copyfile(str(prepared), str(artifact))
        _ndo_ndo_offline__os.chmod(str(artifact), 384)
        digest = _ndo_ndo_offline__hashlib.sha256()
        with artifact.open('rb') as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                digest.update(chunk)

        @_ndo_ndo_offline__contextmanager
        def open_backup():
            with artifact.open('rb') as stream:
                yield stream
        result = _ndo_unified__validate_suite(validate_ndo_suite, open_backup, source_release=release, source_label='offline-ndo-backup', max_uncompressed_bytes=args.ndo_max_backup_bytes, archive_name=artifact.name, archive_size_bytes=artifact.stat().st_size, archive_sha256=digest.hexdigest(), configuration_check_scope='all-reviewed' if args.ndo_all_defect_checks else None)
        status = result.status
        if _configuration_coverage_is_incomplete(result):
            status = 'INCOMPLETE' if status != 'FAIL' else status
        if snapshot['stale'] and status == 'PASS':
            status = 'WARNING'
        component = _ndo_unified__component(result)
        component.update(mode='offline', input_name=source.name, source_release=release, snapshot=snapshot, status=status)
        _controller.generate_report({}, None, status, ndo=component, results_dir=str(root))
        (root / 'ndo-evidence' / 'configuration-checks.log').write_text(result.defect_debug_log(), encoding='utf-8')
        code = 2 if status in ('FAIL', 'INCOMPLETE') else 0
        log.info('Offline NDO validation completed: %s', status)
        handler.flush()
        bundle = working / ('nd-preupgrade-validation-results_' + started.strftime('%Y%m%d_%H%M%S_%f') + '.tgz')
        _ndo_ndo_offline___bundle(root, bundle, artifact if not _ndo_ndo_offline__filecmp.cmp(str(source), str(artifact), shallow=False) else None, args.ndo_bundle_backup_max_bytes)
        print('Results Bundle: {}\n'.format(bundle))
        return code
    except Exception as error:
        log.exception('Offline NDO validation failed')
        print('Offline NDO validation error: {}'.format(error), file=_ndo_ndo_offline__sys.stderr)
        if handler is not None:
            try:
                failure = {'mode': 'offline', 'input_name': source.name, 'status': 'INCOMPLETE', 'completed': False, 'exit_code': 1, 'customer_actions': ['Review the input error and provide a complete supported backup.'], 'error': str(error)}
                _controller.generate_report({}, None, 'INCOMPLETE', ndo=failure, results_dir=str(root))
                config_log.write_text('Offline preparation or validation did not complete.\n', encoding='utf-8')
                handler.flush()
                _ndo_ndo_offline___bundle(root, working / ('nd-preupgrade-validation-results_' + started.strftime('%Y%m%d_%H%M%S_%f') + '.tgz'), None, args.ndo_bundle_backup_max_bytes)
            except OSError as publication_error:
                print('Could not publish offline error report: {}'.format(publication_error), file=_ndo_ndo_offline__sys.stderr)
        return 1
    finally:
        if handler is not None:
            handler.close()
            log.removeHandler(handler)
        if stage is not None:
            _ndo_ndo_offline__shutil.rmtree(str(stage))

# Unified validation presentation (standalone utility printers stay separate).
from contextvars import ContextVar as _ndo_unified__ContextVar
_ndo_unified__retain_all = _ndo_unified__ContextVar('ndo_report_retain_all', default=False)

def _ndo_unified__validate_suite(validate, *args, **kwargs):
    token = _ndo_unified__retain_all.set(True)
    try:
        return validate(*args, **kwargs)
    finally:
        _ndo_unified__retain_all.reset(token)

def _ndo_unified__publish_evidence(root, component):
    source = root / 'diagnostics' / 'ndo'
    destination = root / 'ndo-evidence'
    if source.exists():
        if source.is_symlink() or not source.is_dir() or destination.is_symlink():
            raise ValueError('Unsafe NDO evidence directory')
        if destination.exists():
            if not destination.is_dir():
                raise ValueError('Unsafe NDO evidence destination')
            # Repeated runs retain previously collected archives, as the base does.
            for child in source.iterdir():
                target = destination / child.name
                if child.is_symlink() or not child.is_file() or target.is_symlink():
                    raise ValueError('Unsafe NDO evidence file')
                child.replace(target)
            source.rmdir()
        else:
            source.rename(destination)
        parent = root / 'diagnostics'
        if not any(parent.iterdir()):
            parent.rmdir()
        backup = component.get('backup', {})
        if backup.get('path'):
            backup['path'] = str(destination / _ndo_ndo_integration__Path(backup['path']).name)

def _ndo_unified__component(suite):
    token = _ndo_unified__retain_all.set(True)
    try:
        component = suite.as_dict()
    finally:
        _ndo_unified__retain_all.reset(token)
    component['no_configuration'] = suite.no_configuration
    if suite.defect_validation is not None:
        config = component['configuration_checks']
        for row, decision in zip(config['checks'], (c for c in suite.defect_validation.checks if c.state != 'SKIPPED')):
            if decision.state == 'MATCHED':
                row['affected_objects'] = [_ndo_ndo_checks_ndo_defect_validation___customer_object(decision, obj) for obj in decision.affected_objects]
                row['affected_objects_omitted'] = 0
            row['explanation'] = decision.issue_message if decision.state == 'MATCHED' else decision.reason
            row['recommendation'] = decision.remediation.replace('preupgrade-support_<timestamp>.tgz', 'nd-preupgrade-validation-results_<timestamp>.tgz')
            if decision.coverage_incomplete:
                row['coverage'] = 'incomplete'
    return component

def _ndo_unified__safe(value):
    return ' '.join(_ndo_ndo_integration__re.sub(r'[\x00-\x1f\x7f-\x9f]+', ' ', str(value)).split())

def _ndo_unified__status(status):
    if status in ('PASS', 'NOT_APPLICABLE', 'ABSENT', 'CLEAR', 'SKIPPED'):
        return 'PASS', 'complete'
    if status in ('FAIL', 'WARNING'):
        return status, 'complete'
    return 'WARNING', 'incomplete'

def _ndo_unified__row(name, status, explanation='', recommendation='', findings=()):
    normalized, coverage = _ndo_unified__status(status)
    if status == 'NOT_APPLICABLE':
        explanation = 'Not applicable to this release. ' + explanation
    return dict(name=name, status=normalized, coverage=coverage, note='Not applicable to this release.' if status == 'NOT_APPLICABLE' else '', nodes={}, reference=None,
                explanation=explanation or 'The selected NDO backup passed this check.',
                recommendation=recommendation or 'No action required for this check.', findings=list(findings))

def _ndo_unified__rows(component):
    rows = {}
    config = component.get('configuration_checks', {})
    checks = component.get('preupgrade_checks', [])
    if component.get('enabled') is False or not checks:
        disabled = component.get('enabled') is False
        rows['ndo_status'] = _ndo_unified__row('NDO', 'PASS' if disabled else 'WARNING' if component.get('status') in ('PASS', 'WARNING', 'ABSENT', 'NOT_APPLICABLE') else component.get('status', 'INCOMPLETE'),
            'NDO is not enabled.' if disabled else 'NDO validation did not produce a complete set of backup checks.',
            'No NDO action required.' if disabled else ' '.join(component.get('customer_actions', [])) or 'Collect a complete NDO backup and rerun validation.')
        if disabled:
            rows['ndo_status']['note'] = 'NDO is not enabled.'
        return rows
    no_config = any('no configuration' in str(c).lower() for c in checks if c.get('status') == 'WARNING')
    if no_config or component.get('no_configuration'):
        rows['ndo_status'] = _ndo_unified__row('NDO', 'WARNING',
            'NDO is enabled but holds no configuration. There is no NDO configuration to migrate.',
            'Verify that NDO is intentionally unused. Contact Cisco TAC if configuration was expected.')
        return rows
    for i, check in enumerate(checks):
        findings = check.get('findings') or check.get('display_findings') or []
        objects = []
        for finding in findings:
            detail = ' '.join(str(v) for v in finding) if isinstance(finding, (list, tuple)) else str(finding)
            if detail.startswith('Missing required collection group(s):'):
                detail = detail.replace('legacy_policies', 'legacy policies')
            objects.append({'Details': detail})
        name = {'backup_archive_integrity': 'Backup Archive Integrity', 'required_mongo_collections': 'Required Collections', 'mongo_json_integrity': 'Document Integrity'}.get(check.get('key'), check['title'])
        row = _ndo_unified__row('NDO: ' + str(name), check['status'],
            check.get('why_this_fails') or {'backup_archive_integrity': 'The NDO backup archive is readable and its integrity checks completed.', 'required_mongo_collections': 'Required NDO Mongo collections are present.', 'mongo_json_integrity': 'All NDO Mongo collection records parsed successfully.'}.get(check.get('key'), ''), check.get('recommended_action', ''))
        if objects:
            row['findings'] = [dict(title=check['title'], affected_objects=objects, affected_object_count=len(objects), explanation=row['explanation'], recommendation=row['recommendation'])]
        rows['ndo_preupgrade_' + str(i)] = row
    snapshot = component.get('snapshot', {})
    stamp = _ndo_unified__header(component)[-2].split(': ', 1)[1].split(' (', 1)[0]
    age = _ndo_unified__age(snapshot.get('age_seconds')).replace(' old', ' ago')
    rows['ndo_snapshot_age'] = _ndo_unified__row('NDO: Snapshot Age', 'WARNING' if snapshot.get('stale') else 'PASS',
        'Findings reflect the configuration as of {}, {}.'.format(stamp, age),
        'Validate a fresh NDO export before upgrading.')
    findings = [dict(c) for c in config.get('checks', []) if c.get('status') not in ('PASS', 'NOT_APPLICABLE', 'CLEAR', 'SKIPPED') or c.get('affected_objects')]
    status = config.get('status', 'INCOMPLETE')
    if config.get('coverage_complete') is False and status != 'FAIL':
        status = 'INCOMPLETE'
    rows['ndo_configuration'] = _ndo_unified__row('NDO: Configuration Checks', status,
        config.get('reason', '') or ('Applicable NDO configuration checks completed.' if status == 'PASS' else 'Review the configuration findings and coverage limitations below.'),
        'No action required for this check.' if status in ('PASS', 'NOT_APPLICABLE') else 'Resolve the findings in live NDO, take a fresh backup and rerun validation.', findings)
    limitations = config.get('coverage_limitations', [])
    if config.get('coverage_complete') is False:
        rows['ndo_configuration']['coverage'] = 'incomplete'
    coverage_action = 'Collect a fresh NDO backup and rerun validation; if this persists, open a TAC SR with the results bundle'
    remaining = []
    for item in limitations:
        finding = next((f for f in findings if f.get('title') == item.get('name')), None)
        if finding is None:
            remaining.append(item)
        elif not finding.get('affected_objects'):
            finding['explanation'] = item.get('reason') or finding.get('details')
            finding['recommendation'] = coverage_action
        else:
            finding['explanation'] = (finding.get('explanation', '') + ' ' + item.get('reason', '')).strip()
    for finding in findings:
        if not finding.get('affected_objects') and finding.get('status') in ('INCOMPLETE', 'NOT_EVALUABLE', 'WARNING'):
            finding['explanation'] = finding.get('explanation') or finding.get('details') or 'Required configuration evidence is unavailable.'
            finding['recommendation'] = coverage_action
    rows['ndo_configuration']['coverage_limitations'] = remaining
    # Preserve component-level failures and incomplete coverage even if individual rows look clear.
    if component.get('status') == 'FAIL' and not any(r['status'] == 'FAIL' for r in rows.values()):
        rows['ndo_configuration']['status'] = 'FAIL'
        rows['ndo_configuration']['explanation'] = 'The NDO validation stage did not complete successfully.'
        rows['ndo_configuration']['recommendation'] = ' '.join(component.get('customer_actions', [])) or 'Collect a fresh NDO backup and rerun validation.'
    if component.get('status') == 'INCOMPLETE':
        rows['ndo_configuration']['coverage'] = 'incomplete'
        if rows['ndo_configuration']['status'] != 'FAIL':
            rows['ndo_configuration']['status'] = 'WARNING'
            rows['ndo_configuration']['recommendation'] = 'Collect a complete NDO backup and rerun validation.'
    return rows

def _ndo_unified__table(objects, limit):
    if not objects:
        return []
    objects = [{loc['label']: loc['value'] for loc in obj['location']} if isinstance(obj.get('location'), list) else obj for obj in objects]
    columns = list(dict.fromkeys(key for obj in objects for key in obj))
    visible = objects if limit is None else objects[:limit]
    widths = [max(len(key), *(len(_ndo_unified__safe(obj.get(key, ''))) for obj in visible)) for key in columns]
    def line(values):
        return '  ' + '  '.join(value.ljust(width) for value, width in zip(values, widths)).rstrip()
    lines = [line(columns), line(['-' * width for width in widths])]
    lines += [line([_ndo_unified__safe(obj.get(key, '')) for key in columns]) for obj in visible]
    return lines

def _ndo_unified__paragraph(label, value):
    import textwrap
    return ['', '  ' + label + ':'] + textwrap.wrap(_ndo_unified__safe(value), width=96, initial_indent='  ', subsequent_indent='  ', break_long_words=False, break_on_hyphens=False)

def _ndo_unified__row_lines(row, limit):
    if row['status'] == 'PASS':
        return []
    lines = []
    findings = row.get('findings', [])
    for i, finding in enumerate(findings, 1):
        objects = finding.get('affected_objects', [])
        count = finding.get('affected_object_count', len(objects))
        heading = '{} affected object{}'.format(count, '' if count == 1 else 's') if count else 'could not be fully evaluated'
        lines += ['', '  Finding {} of {}: {} ({})'.format(i, len(findings), _ndo_unified__safe(finding.get('title', row['name'])), heading)]
