def _ndo_ndo_checks_ndo_validation___append_bounded(items, value):
    if _ndo_unified__retain_all.get() or len(items) < _ndo_ndo_checks_ndo_validation__MAX_RETAINED_DETAILS:
        items.append(value)

def _ndo_ndo_checks_ndo_validation___extend_bounded(items, values):
    for value in values:
        _ndo_ndo_checks_ndo_validation___append_bounded(items, value)

def _ndo_ndo_checks_ndo_validation___observe_collection_document(filename, row, summary):
    if filename == 'msc_tenant.json':
        name = str(row.get('name') or row.get('displayName') or '')
        for prefix in _ndo_ndo_checks_ndo_validation__RESERVED_TENANT_PREFIXES:
            if name.lower().startswith(prefix):
                summary.add_failure("{0} matches reserved prefix '{1}'".format(name, prefix))
                break
        return
    if filename == 'msc_dbOverhaulProgress.json':
        for key in ('templatesAnalysisStatus', 'localDeployStatus', 'restoreStatus', 'stage', 'status'):
            value = str(row.get(key, '')).lower()
            if value in _ndo_ndo_checks_ndo_validation__FAILURE_VALUES:
                summary.add_failure('{0}={1}'.format(key, row.get(key)))
            elif value in _ndo_ndo_checks_ndo_validation__RUNNING_VALUES:
                summary.add_warning('{0}={1}'.format(key, row.get(key)))
        return
    if filename in _ndo_ndo_checks_ndo_validation__BACKUP_RECORD_COLLECTION_ALIASES:
        name = row.get('name') or row.get('_id') or 'backup'
        entry = row.get('backupEntry') if isinstance(row.get('backupEntry'), dict) else {}
        restore_logs = entry.get('restoreLogs') if isinstance(entry.get('restoreLogs'), dict) else {}
        if restore_logs.get('hasError'):
            summary.add_failure('{0}: restore log hasError=true'.format(name))
        if restore_logs.get('hasWarning'):
            summary.add_warning('{0}: restore log hasWarning=true'.format(name))
        return
    if filename in _ndo_ndo_checks_ndo_validation__ACTIVE_TASK_COLLECTIONS:
        status = _ndo_ndo_checks_ndo_validation___first_status(row)
        if status in _ndo_ndo_checks_ndo_validation__FAILURE_VALUES:
            summary.add_failure('{0}: status={1}'.format(filename, status))
        elif status in _ndo_ndo_checks_ndo_validation__RUNNING_VALUES:
            summary.add_warning('{0}: status={1}'.format(filename, status))

def _ndo_ndo_checks_ndo_validation__validate_native_backup(backup_path, api_client, release='pre-3.3'):
    checks = {'native_backup_archive': _ndo_ndo_checks_ndo_validation___check_native_archive(_ndo_ndo_checks_ndo_validation__Path(backup_path))}
    tenant_status, tenant_payload = api_client.get_with_status('/mso/api/v1/tenants')
    if tenant_status != 200:
        checks['reserved_tenant_names'] = _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Tenant validation returned HTTP {0}'.format(tenant_status)])
    else:
        tenants = _ndo_ndo_checks_ndo_validation___response_rows(tenant_payload, 'tenants')
        checks['reserved_tenant_names'] = _ndo_ndo_checks_ndo_validation___check_reserved_tenants(tenants) if tenants is not None else _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Tenant response was malformed'])
    backup_status, backup_payload = api_client.get_with_status('/mso/api/v1/backups')
    if backup_status == 404:
        checks['backup_restore_health'] = _ndo_ndo_checks_ndo_validation___not_applicable('Backup record API is unavailable on {0}'.format(release))
    elif backup_status != 200:
        checks['backup_restore_health'] = _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Backup record validation returned HTTP {0}'.format(backup_status)])
    else:
        rows = _ndo_ndo_checks_ndo_validation___response_rows(backup_payload, 'backups')
        checks['backup_restore_health'] = _ndo_ndo_checks_ndo_validation___check_backup_records(rows) if rows is not None else _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Backup record response was malformed'])
    unavailable_detail = 'JSON backup export is unavailable on {0}; this check was not run'.format(release)
    for name in ('json_parse_integrity', 'required_collections', 'db_overhaul_progress', 'active_task_backlog'):
        checks[name] = _ndo_ndo_checks_ndo_validation___not_applicable(unavailable_detail)
    return _ndo_ndo_checks_ndo_validation___result('native', checks, 0, 0)

def _ndo_ndo_checks_ndo_validation___result(mode, checks, collection_count, document_count):
    executed = sorted((name for name, check in checks.items() if check.status != 'NOT_APPLICABLE'))
    not_applicable = sorted((name for name, check in checks.items() if check.status == 'NOT_APPLICABLE'))
    return _ndo_ndo_checks_ndo_validation__ValidationResult(mode=mode, checks=checks, coverage={'executed': executed, 'not_applicable': not_applicable}, collection_count=collection_count, document_count=document_count)

def _ndo_ndo_checks_ndo_validation___check_required_collections(collections, healthy_version_metadata=False):
    missing = [group for group, candidates in _ndo_ndo_checks_ndo_validation__CORE_COLLECTION_GROUPS.items() if not any((candidate in collections for candidate in candidates))]
    if len(missing) == len(_ndo_ndo_checks_ndo_validation__CORE_COLLECTION_GROUPS) and healthy_version_metadata and all((name in collections for name in _ndo_ndo_checks_ndo_validation__EMPTY_STATE_SYSTEM_COLLECTIONS)):
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', [_ndo_ndo_checks_ndo_validation__NO_CONFIGURATION_DETAIL])
    is_legacy = 'msc_schema.json' in collections and 'msc_schema2.json' not in collections
    if is_legacy and 'msc_policy.json' not in collections:
        missing.append('legacy_policies')
    if missing:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Missing required collection group(s): {0}'.format(', '.join(missing))])
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['Required NDO backup collections are present'])

def _ndo_ndo_checks_ndo_validation___check_json_integrity(errors):
    if errors:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', errors if _ndo_unified__retain_all.get() else errors[:20])
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['All NDO collection records parsed as JSON'])

def _ndo_ndo_checks_ndo_validation___check_reserved_tenants(tenants):
    if isinstance(tenants, _ndo_ndo_checks_ndo_validation___CollectionSummary):
        if tenants.failures:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', list(tenants.failures))
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['No reserved tenant prefixes found ({0} checked)'.format(tenants.document_count)])
    flagged = []
    for tenant in tenants:
        if not isinstance(tenant, dict):
            continue
        name = str(tenant.get('name') or tenant.get('displayName') or '')
        for prefix in _ndo_ndo_checks_ndo_validation__RESERVED_TENANT_PREFIXES:
            if name.lower().startswith(prefix):
                flagged.append("{0} matches reserved prefix '{1}'".format(name, prefix))
                break
    if flagged:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', flagged)
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['No reserved tenant prefixes found ({0} checked)'.format(len(tenants))])

def _ndo_ndo_checks_ndo_validation___check_db_overhaul(rows):
    if isinstance(rows, _ndo_ndo_checks_ndo_validation___CollectionSummary):
        if rows.document_count == 0:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', ['No dbOverhaul progress records found'])
        if rows.failures:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', list(rows.failures))
        if rows.warnings:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', list(rows.warnings))
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['dbOverhaul progress records are complete'])
    if not rows:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', ['No dbOverhaul progress records found'])
    failures = []
    running = []
    for row in rows:
        for key in ('templatesAnalysisStatus', 'localDeployStatus', 'restoreStatus', 'stage', 'status'):
            value = str(row.get(key, '')).lower()
            if value in _ndo_ndo_checks_ndo_validation__FAILURE_VALUES:
                failures.append('{0}={1}'.format(key, row.get(key)))
            elif value in _ndo_ndo_checks_ndo_validation__RUNNING_VALUES:
                running.append('{0}={1}'.format(key, row.get(key)))
    if failures:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', failures)
    if running:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', running)
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['dbOverhaul progress records are complete'])

def _ndo_ndo_checks_ndo_validation___check_backup_records(rows):
    if isinstance(rows, _ndo_ndo_checks_ndo_validation___CollectionSummary):
        if rows.document_count == 0:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', ['No backup records found'])
        if rows.failures:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', list(rows.failures))
        if rows.warnings:
            return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', list(rows.warnings))
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['Backup restore records do not report errors'])
    if not rows:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', ['No backup records found'])
    failures = []
    warnings = []
    for row in rows:
        if not isinstance(row, dict):
            failures.append('Backup record was not an object')
            continue
        name = row.get('name') or row.get('_id') or 'backup'
        entry = row.get('backupEntry') if isinstance(row.get('backupEntry'), dict) else {}
        restore_logs = entry.get('restoreLogs') if isinstance(entry.get('restoreLogs'), dict) else {}
        if restore_logs.get('hasError'):
            failures.append('{0}: restore log hasError=true'.format(name))
        if restore_logs.get('hasWarning'):
            warnings.append('{0}: restore log hasWarning=true'.format(name))
    if failures:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', failures)
    if warnings:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', warnings)
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['Backup restore records do not report errors'])

def _ndo_ndo_checks_ndo_validation___check_backup_record_collections(collections):
    reviewed = [(filename, _ndo_ndo_checks_ndo_validation___check_backup_records(collections[filename])) for filename in _ndo_ndo_checks_ndo_validation__BACKUP_RECORD_COLLECTION_ALIASES if filename in collections]
    if not reviewed:
        return _ndo_ndo_checks_ndo_validation___not_applicable('Backup record collection is not present; this check was not run')
    if len(reviewed) == 1:
        return reviewed[0][1]
    statuses = [check.status for _, check in reviewed]
    if 'FAIL' in statuses:
        status = 'FAIL'
    elif 'WARNING' in statuses:
        status = 'WARNING'
    else:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['Backup restore records do not report errors'])
    details = []
    for filename, check in reviewed:
        if check.status not in ('FAIL', 'WARNING'):
            continue
        for detail in check.details:
            _ndo_ndo_checks_ndo_validation___append_bounded(details, '{0}: {1}'.format(filename, detail))
    return _ndo_ndo_checks_ndo_validation__ValidationCheck(status, details)

def _ndo_ndo_checks_ndo_validation___check_active_tasks(collections):
    active = []
    failed = []
    for name in _ndo_ndo_checks_ndo_validation__ACTIVE_TASK_COLLECTIONS:
        rows = collections.get(name, _ndo_ndo_checks_ndo_validation___CollectionSummary())
        if isinstance(rows, _ndo_ndo_checks_ndo_validation___CollectionSummary):
            _ndo_ndo_checks_ndo_validation___extend_bounded(failed, rows.failures)
            _ndo_ndo_checks_ndo_validation___extend_bounded(active, rows.warnings)
        else:
            for row in rows:
                status = _ndo_ndo_checks_ndo_validation___first_status(row)
                if status in _ndo_ndo_checks_ndo_validation__FAILURE_VALUES:
                    _ndo_ndo_checks_ndo_validation___append_bounded(failed, '{0}: status={1}'.format(name, status))
                elif status in _ndo_ndo_checks_ndo_validation__RUNNING_VALUES:
                    _ndo_ndo_checks_ndo_validation___append_bounded(active, '{0}: status={1}'.format(name, status))
    if failed:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', failed if _ndo_unified__retain_all.get() else failed[:20])
    if active:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('WARNING', active if _ndo_unified__retain_all.get() else active[:20])
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['No active or failed task backlog detected'])

def _ndo_ndo_checks_ndo_validation___first_status(row):
    if not isinstance(row, dict):
        return ''
    for key in ('status', 'state', 'stage', 'deployStatus', 'executionStatus'):
        if key in row:
            return str(row.get(key, '')).lower()
    return ''

def _ndo_ndo_checks_ndo_validation___check_native_archive(path):
    try:
        with _ndo_ndo_checks_ndo_validation__tarfile.open(str(path), 'r:*') as archive:
            nonempty = set()
            for member in archive:
                if not _ndo_ndo_checks_ndo_validation___safe_member_name(member.name):
                    return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Native backup has an unsafe member'])
                if member.isfile() and member.size > 0:
                    nonempty.add(_ndo_ndo_checks_ndo_validation__PurePosixPath(member.name).name)
            missing = sorted({'backup', 'metadata'} - nonempty)
            if missing:
                return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Native backup is missing: {0}'.format(', '.join(missing))])
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('PASS', ['Native backup and metadata are readable'])
    except (OSError, _ndo_ndo_checks_ndo_validation__tarfile.TarError) as exc:
        return _ndo_ndo_checks_ndo_validation__ValidationCheck('FAIL', ['Unable to read native backup archive: {0}'.format(exc)])

def _ndo_ndo_checks_ndo_validation___response_rows(payload, key):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        value = payload.get(key)
        if isinstance(value, list):
            return value
        data = payload.get('data')
        if isinstance(data, list):
            return data
    return None

def _ndo_ndo_checks_ndo_validation___not_applicable(detail):
    return _ndo_ndo_checks_ndo_validation__ValidationCheck('NOT_APPLICABLE', [detail])

def _ndo_ndo_checks_ndo_validation___safe_member_name(name):
    path = _ndo_ndo_checks_ndo_validation__PurePosixPath(name)
    return not path.is_absolute() and '..' not in path.parts
