    known = _ndo_ndo_checks_ndo_customer_checks___POLICY_TYPE_LABELS.get(policy_type)
    if known:
        return known
    words = _ndo_ndo_checks_ndo_customer_checks__re.sub('(?<=[a-z0-9])(?=[A-Z])', ' ', policy_type)
    words = words.replace('_', ' ').replace('-', ' ')
