    if 'edit_config' in lowered or ('template' in lowered and 'version' in lowered and ('state' in lowered)):
        return 'pending_template_configuration'
    if 'deployed policy' in lowered and 'requires' in lowered and ('not deployed' in lowered):
        return 'deployment_dependency_consistency'
    if 'loop' in lowered or 'circular' in lowered or 'traversing' in lowered:
        return 'circular_template_policy_dependencies'
    if 'siteid not found for tenant' in lowered or ('site ' in lowered and 'not found for tenant' in lowered) or ('tenant ' in lowered and 'not found' in lowered) or ('site association' in lowered) or ('site-association' in lowered) or ('dscp translation policy' in lowered):
        return 'site_tenant_association_consistency'
    if 'dropped ' in lowered or 'unsupported template type' in lowered or 'skipping template' in lowered or ('failed to evict' in lowered) or ('both dhcplabel and dhcplabels' in lowered) or ('exceeding max templates' in lowered):
        return 'migration_policy_template_compatibility'
