def _ndo_ndo_checks_ndo_validation_suite___analysis_block(title, status, failure_reason, detail_heading, display_findings, action, width, color, display_finding_total=0, reason_heading='WHY THIS FAILS'):
    status_color = _ndo_ndo_checks_ndo_validation_suite__ANSI_RED if status == 'FAIL' else _ndo_ndo_checks_ndo_validation_suite__ANSI_YELLOW
    groups = tuple(display_findings) or (('Details were not available.',),)
