    lines = [_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, 'PRE-UPGRADE VALIDATION', position='top', label_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color)]
