    lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_line('{0} - ATTENTION REQUIRED'.format(status), width, ansi_color=status_color, color=color))
    lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, reason_heading, label_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color))
    lines.extend(_ndo_ndo_checks_ndo_validation_suite___console_box_wrap('', failure_reason, width))
    lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, detail_heading, label_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color))
    for group_index, group in enumerate(groups, 1):
        if total_groups > 1:
            lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_line('FINDING {0} OF {1}'.format(group_index, total_groups), width, ansi_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color))
        for item in group:
            stripped = item.lstrip()
            indent = ' ' * min(6, len(item) - len(stripped))
            lines.extend(_ndo_ndo_checks_ndo_validation_suite___console_box_wrap(indent, stripped, width, indent, trusted_locator=True, preserve_leading_spacing=True))
        if group_index != len(groups):
            lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_line('', width))
    if omitted_groups:
        lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, 'ADDITIONAL DETAILS', label_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color))
        lines.extend(_ndo_ndo_checks_ndo_validation_suite___console_box_wrap('', additional_details_message(), width))
    lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, 'RECOMMENDED ACTION', label_color=_ndo_ndo_checks_ndo_validation_suite__ANSI_CYAN, color=color))
    lines.extend(_ndo_ndo_checks_ndo_validation_suite___console_box_wrap('', action, width))
    lines.append(_ndo_ndo_checks_ndo_validation_suite___console_box_rule(width, position='bottom'))
    return lines

