def _ndo_ndo_backup_converter_cli___summary_lines(status: 'str', layout: 'str', validation_path: '_ndo_ndo_backup_converter_cli__Optional[_ndo_ndo_backup_converter_cli__Path]', product_path: '_ndo_ndo_backup_converter_cli__Optional[_ndo_ndo_backup_converter_cli__Path]', blockers: '_ndo_ndo_backup_converter_cli__Sequence[str]', checks_exit: '_ndo_ndo_backup_converter_cli__Optional[int]'=None, validation_status: '_ndo_ndo_backup_converter_cli__Optional[str]'=None, artifact_status: '_ndo_ndo_backup_converter_cli__Optional[str]'=None, errors: '_ndo_ndo_backup_converter_cli__Sequence[str]'=()) -> '_ndo_ndo_backup_converter_cli__List[str]':
    lines = ['NDO Backup Conversion Summary', '', f"""Status: {status}""", f"""Detected layout: {layout}"""]
    if artifact_status and artifact_status != status:
        lines.append(f"""Artifact status: {artifact_status}""")
    if validation_path:
        lines.append(f"""Validation backup: {validation_path.name}""")
    if validation_status:
        lines.append(f"""Validation preflight: {validation_status}""")
    if product_path:
        lines.append(f"""Product backup: {product_path.name}""")
    if checks_exit is not None:
        lines.append(f"""NDO checks exit code: {checks_exit}""")
    if status == 'IMPORT_BLOCKED' and layout == 'legacy_embedded':
        lines.extend(('', 'This is a legacy MSO/NDO backup. The converter does not produce an importable', 'backup from legacy data; NDO converts legacy configuration itself when the', 'ORIGINAL backup is restored. Supported path (Cisco "Upgrading Manually Using', 'Configuration Restore"):', '  1. Validate the legacy data: rerun this command with --validation-only', '     --run-ndo-checks, and resolve any findings.', '  2. Deploy the intermediate release from the Cisco migration guide (for very', '     old MSO: ND 3.2.2m / NDO 4.4.3) and restore the ORIGINAL backup there.', '  3. Upgrade to the target ND release.', f"""Conversion review items: {len(blockers)} (see conversion-details.json)."""))
    elif blockers:
        lines.extend(('', 'Native import publication was blocked:', *[f"""- {item}""" for item in blockers[:50]]))
    if status == 'IMPORT_BLOCKED':
        lines.extend(('', 'Use the validation backup with the validation tools. Do not import it into NDO.'))
    if errors:
        lines.extend(('', 'Failure reason:', *[f"""- {item}""" for item in errors[:20]]))
    return lines

