            validation_path = package.path
            details['namespace_dispositions'] = dict(result.namespace_dispositions)
            details['identity_mappings'] = [vars(item) for item in result.identity_mappings]
            details['graph'] = {'source_sha256': verification.source_graph.graph_sha256, 'generated_sha256': verification.generated_graph.graph_sha256, 'equivalent': verification.comparison.equivalent}
            if arguments.validation_only:
                artifact_status = 'VALIDATION_INCOMPLETE' if package.validation.status == 'FAIL' else 'VALIDATION_READY'
