if '_ndo_ndo_backup_converter_cli__ConverterArgumentParser' in globals():
    _ndo_ndo_backup_converter_cli__ConverterArgumentParser.__name__ = 'ConverterArgumentParser'

# Former module: ndo_backup_converter.contracts
"""Packaged, customer-data-free backup layout contracts."""
def _ndo_dispatch(parser, args):
    """Validate mode-specific options before any live probes or credentials."""
    mode_names = ("tech_support", "extract_backup", "convert_backup", "mongodump_to_json", "check_backup", "check_defects")
    selected = next((name for name in mode_names if getattr(args, name) is not None), None)
    shared = {"source_release", "output_dir"}
    allowed = {
        "tech_support": {"source_release", "ndo_max_backup_bytes", "ndo_bundle_backup_max_bytes", "ndo_all_defect_checks"},
        "extract_backup": {"output_dir"},
        "convert_backup": shared | {"name", "validation_only", "run_ndo_checks", "max_input_bytes", "max_expanded_bytes"},
        "mongodump_to_json": {"output_dir", "json_mode", "output_tar"},
        "check_backup": shared | {"max_uncompressed_bytes"},
        "check_defects": shared | {"max_uncompressed_bytes"},
    }
    options = {"source_release", "output_dir", "name", "validation_only", "run_ndo_checks", "max_input_bytes", "max_expanded_bytes", "max_uncompressed_bytes", "json_mode", "output_tar"}
    supplied = {token.split("=", 1)[0] for token in sys.argv[1:]}
    if selected:
        live = {"ndip", "password", "api_username", "api_password", "domain", "diagnose", "bash"}
        conflicts = [name for name in live if getattr(args, name) not in (None, False)]
        conflicts += [name for name in options - allowed[selected] if getattr(args, name) not in (None, False)]
        for name in ("ndo_max_backup_bytes", "ndo_bundle_backup_max_bytes", "ndo_all_defect_checks"):
            if name not in allowed[selected] and "--" + name.replace("_", "-") in supplied:
                conflicts.append(name)
        if conflicts:
            parser.error("--" + selected.replace("_", "-") + " cannot be combined with " + ", ".join("--" + name.replace("_", "-") for name in sorted(conflicts)))
    else:
        conflicts = [name for name in options if getattr(args, name) not in (None, False)]
        if conflicts:
            parser.error("offline options require an NDO offline mode: " + ", ".join("--" + name.replace("_", "-") for name in sorted(conflicts)))
        return None
    source = getattr(args, selected)
    if selected == "tech_support":
        return _ndo_ndo_offline__run_offline(args)
    if selected in ("extract_backup", "convert_backup") and not args.output_dir:
        parser.error("--output-dir is required for --" + selected.replace("_", "-"))
    if selected == "extract_backup":
        return _ndo_techsupport_to_ndo_backup__main(["--tech-support", source, "--output-dir", args.output_dir])
    if selected == "convert_backup":
        argv = ["--input", source, "--output-dir", args.output_dir]
        for name in ("name", "source_release", "max_input_bytes", "max_expanded_bytes"):
            if getattr(args, name) is not None:
                argv.extend(["--" + name.replace("_", "-"), str(getattr(args, name))])
        for name in ("validation_only", "run_ndo_checks"):
            if getattr(args, name):
                argv.append("--" + name.replace("_", "-"))
        return _ndo_ndo_backup_converter_cli__main(argv)
    if selected == "mongodump_to_json":
        if args.output_tar and args.output_dir:
            parser.error("output_tar cannot be combined with --output-dir")
        argv = [source]
        if args.output_tar:
            argv.append(args.output_tar)
        elif args.output_dir:
            output = _ndo_mongodump_archive_to_json__Path(args.output_dir)
            output.mkdir(parents=True, exist_ok=True)
            argv.append(str(output / (_ndo_mongodump_archive_to_json__Path(source).name + "-json.tar.gz")))
        argv.extend(["--json-mode", args.json_mode or "relaxed"])
        return _ndo_mongodump_archive_to_json__main(argv)
    if not args.source_release:
        parser.error("--source-release is required for --" + selected.replace("_", "-"))
    argv = ["--backup", source, "--source-release", args.source_release]
    for name in ("output_dir", "max_uncompressed_bytes"):
        if getattr(args, name) is not None:
            argv.extend(["--" + name.replace("_", "-"), str(getattr(args, name))])
    if selected == "check_backup":
        return _ndo_ndo_checks_ndo_validation_suite__main(argv)
    return _ndo_ndo_checks_ndo_defect_validation__main(argv)
